--
-- Playable Ogres (Horde), race id 9 - PROTOTYPE: character creation, class choice, entering the world.
-- GENERATED by client-patches/ogre-race/build_ogre_race.py together with the client files
-- (-> patch-enGB-4) - edit the builder, not this file.
--
-- Classes: Warrior (one-headed, the male slot), Shaman / Mage / Warlock (two-headed, the female slot).
-- No racial abilities, no reputation masks, no quest race masks yet. Nothing in C++.
-- Everything is read at startup: restart the worldserver.
--

-- ChrRaces.dbc row 9 (was the non-playable Goblin). RaceMgr::LoadRaces takes the playable races and their
-- side from this store: flags without NOT_PLAYABLE, Alliance column 1 = Horde, BaseLanguage 1 = Horde team.
DELETE FROM `chrraces_dbc` WHERE `ID` = 9;

-- The two bodies. The core asserts on a player display without these rows (Unit::GetCollisionHeight).
DELETE FROM `creaturemodeldata_dbc` WHERE `ID` IN (3500, 3501);
DELETE FROM `creaturedisplayinfo_dbc` WHERE `ID` IN (33000, 33001);
-- Unit::SetDisplayId sets the gender byte from this table: a stock ogre display (gender 0) would turn
-- every two-headed ogre into a "male" one at login.
DELETE FROM `creature_model_info` WHERE `DisplayID` IN (33000, 33001);

-- CharSections.dbc: the server only needs it for mod-playerbots, which picks a random face and hair from
-- this store when it creates a bot and indexes an empty list otherwise.
DELETE FROM `charsections_dbc` WHERE `ID` BETWEEN 15000 AND 15039;

-- The four race / class pairs: they start where the orcs do.
DELETE FROM `playercreateinfo` WHERE `race` = 9;
SELECT 9, c.`class`, p.`map`, p.`zone`, p.`position_x`, p.`position_y`, p.`position_z`, p.`orientation`
FROM `playercreateinfo` p
JOIN (SELECT 1 AS `class` UNION ALL SELECT 7 AS `class` UNION ALL SELECT 8 AS `class` UNION ALL SELECT 9 AS `class`) c
WHERE p.`race` = 2 AND p.`class` = 1;

-- Stat modifiers of the race: the tauren's for now.
DELETE FROM `player_race_stats` WHERE `Race` = 9;
SELECT 9, `Strength`, `Agility`, `Stamina`, `Intellect`, `Spirit` FROM `player_race_stats` WHERE `Race` = 6;

-- Race-masked starting skills (the rest comes by class): Orcish; two-handed and one-handed maces for the warrior.
DELETE FROM `playercreateinfo_skills` WHERE `raceMask` = 256;

-- Starting action bars
DELETE FROM `playercreateinfo_action` WHERE `race` = 9;

-- Starting items (CharStartOutfit.dbc rows: ItemID x24, DisplayItemID x24, InventoryType x24), both bodies per class
--   Warrior: Brawler's Harness (6125), Brawler's Pants (139), Brawler's Boots (140), Battleworn Hammer (2361), Tough Jerky (117), Hearthstone (6948)
--   Shaman: Primitive Mantle (154), Primitive Kilt (153), Worn Mace (36), Tough Jerky (117), Refreshing Spring Water (159), Hearthstone (6948)
--   Mage: Apprentice's Shirt (6096), Apprentice's Pants (1395), Bent Staff (35), Tough Jerky (117), Refreshing Spring Water (159), Hearthstone (6948)
--   Warlock: Acolyte's Shirt (6097), Acolyte's Pants (1396), Worn Dagger (2092), Tough Jerky (117), Refreshing Spring Water (159), Hearthstone (6948)
DELETE FROM `charstartoutfit_dbc` WHERE `ID` BETWEEN 404 AND 411;

-- SkillRaceClassInfo.dbc: an ogre may have every skill an orc may have (languages, weapons, riding ...):
-- race mask +256 on the 18 rows that list the orc, the orc racial line aside.
-- Rows 632 and 635 are also written by the race-class file (hunter daggers / guns): this file is the later one.
DELETE FROM `skillraceclassinfo_dbc` WHERE `ID` IN (140, 117, 629, 126, 635, 637, 41, 48, 441, 94, 481, 442, 621, 632, 634, 446, 464, 781);

-- SkillLineAbility.dbc: an ogre gets / may learn every spell an orc does (the orc racial line aside):
-- race mask +256 on the 18 rows that list the orc. Among them 669 Language (Orcish), given with skill 109 -
-- without the SPELL the client offers no language and nothing can be typed in chat. Also Bloodlust, the
-- Horde teleports and portals. Characters that exist already get the spell at their next login.
DELETE FROM `skilllineability_dbc` WHERE `ID` IN (592, 3271, 3273, 3274, 5991, 5993, 5994, 13151, 14816, 14818, 15606, 15607, 17000, 17003, 20110, 20290, 21723, 21724);
